{"path": "/work/test_author_match_spec.py", "content": """"Scratch conformance checks for the new author-matching spec (not part of repo)."""
import web
import pytest

from openlibrary.mocks.mock_infobase import mock_site  # noqa: F401  (fixture import)
from openlibrary.catalog.add_book.load_book import (
    find_author,
    find_entity,
    import_author,
)


def save(site, key, **kw):
    doc = {
        'key': key,
        'type': {'key': '/type/author'},
        'name': kw.pop('name'),
    }
    doc.update(kw)
    site.save(web.storage(doc))
    return doc


def keys(found):
    return [a['key'] for a in found]


class TestNameDates:
    def test_case_insensitive_name_fallback_when_date_missing(self, mock_site):
        save(mock_site, '/a/OL1A', name='John Smith', birth_date='1980', death_date='1990')
        # Only birth given, and it does not match: name-only fallback still resolves.
        assert find_entity(
            {'name': 'john smith', 'birth_date': '1111'}
        )['key'] == '/a/OL1A'

    def test_year_mismatch_invalidates_when_both_dates(self, mock_site):
        save(mock_site, '/a/OL1A', name='John Smith', birth_date='1980', death_date='1990')
        assert find_entity({'name': 'John Smith', 'birth_date': '1980', 'death_date': '1999'}) is None

    def test_exact_dates_take_precedence(self, mock_site):
        save(mock_site, '/a/OL2A', name='Smith, John', birth_date='1980')
        save(mock_site, '/a/OL1A', name='Smith, John', birth_date='1980', death_date='1990')
        # OL1 has both years exact; OL2 only birth. Exact match first (despite higher key num of OL2)
        assert find_entity(
            {'name': 'Smith, John', 'birth_date': '1980', 'death_date': '1990'}
        )['key'] == '/a/OL1A'


class TestAlternateNames:
    def test_alternate_names_with_exact_dates(self, mock_site):
        save(
            mock_site,
            '/a/OL3A',
            name='Samuel Clemens',
            alternate_names=['Mark Twain', 'Clemens, Samuel'],
            birth_date='1835',
            death_date='1910',
        )
        found = find_author(
            {'name': 'Mark Twain', 'birth_date': '1835', 'death_date': '1910.'}
        )
        assert keys(found) == ['/a/OL3A']

    def test_alternate_names_requires_both_dates(self, mock_site):
        save(
            mock_site,
            '/a/OL3A',
            name='Samuel Clemens',
            alternate_names=['Mark Twain'],
            birth_date='1835',
            death_date='1910',
        )
        assert find_author({'name': 'Mark Twain', 'birth_date': '1835'}) == []
        assert find_author({'name': 'Mark Twain'}) == []

    def test_alternate_names_date_mismatch_rejected(self, mock_site):
        save(
            mock_site,
            '/a/OL3A',
            name='Samuel Clemens',
            alternate_names=['Mark Twain'],
            birth_date='1835',
            death_date='1910',
        )
        assert find_author({'name': 'Mark Twain', 'birth_date': '1800', 'death_date': '1910'}) == []


class TestSurname:
    def test_surname_with_exact_dates(self, mock_site):
        save(mock_site, '/a/OL5A', name='Samuel Clemens', birth_date='1835', death_date='1910')
        found = find_author(
            {'name': 'Samuel Langhorne Clemens', 'birth_date': '1835', 'death_date': '1910.'}
        )
        assert keys(found) == ['/a/OL5A']

    def test_surname_not_matched_without_both_dates(self, mock_site):
        save(mock_site, '/a/OL5A', name='Samuel Clemens', birth_date='1835', death_date='1910')
        assert find_author({'name': 'Samuel Langhorne Clemens'}) == []
        assert find_author({'name': 'Samuel Langhorne Clemens', 'birth_date': '1835'}) == []

    def test_surname_not_matched_on_date_mismatch(self, mock_site):
        save(mock_site, '/a/OL5A', name='Samuel Clemens', birth_date='1835', death_date='1910')
        assert (
            find_author(
                {'name': 'Samuel Langhorne Clemens', 'birth_date': '1835', 'death_date': '1911'}
            )
            == []
        )

    def test_name_before_surname(self, mock_site):
        save(mock_site, '/a/OL1A', name='Clemens', birth_date='1835', death_date='1910')
        save(mock_site, '/a/OL2A', name='Samuel Clemens', birth_date='1835', death_date='1910')
        # Direct name (flipped/alternate?) no; surname path finds both, exact dates; name none.
        # lower OL key first among equal tier:
        found = find_author(
            {'name': 'Langhorne Clemens', 'birth_date': '1835', 'death_date': '1910'}
        )
        assert keys(found) == ['/a/OL1A', '/a/OL2A']


class TestWildcard:
    def test_wildcard_first_by_numeric_key(self, mock_site):
        save(mock_site, '/a/OL10A', name='John Adams')
        save(mock_site, '/a/OL2A', name='john Smith')
        found = find_author({'name': 'John*'})
        # numeric ordering: OL2A before OL10A
        assert keys(found) == ['/a/OL2A', '/a/OL10A']
        assert find_entity({'name': 'John*'})['key'] == '/a/OL2A'

    def test_no_match_new_candidate_preserves_name(self, mock_site):
        a = import_author({'name': 'Nobody*', 'birth_date': '1900', 'death_date': '2000'})
        assert a['name'] == 'Nobody*'
        assert a['birth_date'] == '1900'
        assert a['death_date'] == '2000'


class TestPriority:
    def test_name_beats_alternate_beats_surname(self, mock_site):
        save(mock_site, '/a/OL1A', name='Clemens, Samuel Langhorne', birth_date='1835', death_date='1910')  # surname tier
        save(mock_site, '/a/OL9A', name='Twain, Mark', alternate_names=['Samuel Clemens'], birth_date='1835', death_date='1910')  # alternate tier
        save(mock_site, '/a/OL5A', name='Samuel Langhorne Clemens', birth_date='1835', death_date='1910')  # name tier (flipped)
        found = find_author(
            {'name': 'Samuel Langhorne Clemens', 'birth_date': '1835', 'death_date': '1910'}
        )
        assert keys(found)[0] == '/a/OL5A'
"}

